INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 7, 'theory', 'Квиз: пространства имён');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 7, 0, 'У двух процессов в /proc/PID/ns/net записано одно и то же значение, например net:[4026531840]. Что это значит?', '["У них одинаковые IP-адреса", "Они запущены одним пользователем", "Они находятся в одном сетевом пространстве имён", "У них общий родительский процесс"]', 2, 'Число в скобках это номер индексного дескриптора пространства. Совпавший номер значит одно и то же пространство, а адреса, владелец и родитель тут ни при чём.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 7, 1, 'Зачем к unshare --pid обычно добавляют --fork?', '["Новое PID-пространство получают потомки, а не сам процесс; с форком программа становится дочерней и получает PID 1", "Чтобы команда работала в фоне", "Чтобы получить права рута без sudo", "Чтобы смонтировать свежий /proc"]', 0, 'Процесс не меняет своё PID-пространство после создания. Новое получают только его дети, поэтому программу запускают дочерней. Свежий /proc даёт отдельный ключ --mount-proc.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 7, 2, 'Карта /proc/PID/uid_map содержит строку «0 100000 65536». Какой номер на хосте у процесса, для которого внутри UID равен 5?', '["5", "100000", "65541", "100005"]', 3, 'Диапазон начинается с 0 внутри и 100000 снаружи, значит смещение 5 даёт 100005. Число 65541 это неверное сложение с длиной диапазона.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 7, 3, 'Что происходит с пространством, созданным командой ip netns add red, когда в нём нет ни одного процесса?', '["Оно удаляется сразу", "Оно остаётся: его удерживает файл, смонтированный в /var/run/netns", "Оно сливается с начальным сетевым пространством", "Оно превращается в PID-пространство"]', 1, 'ip netns add монтирует ссылку /proc/self/ns/net поверх файла с именем. Такое монтирование держит пространство живым. Удаляет его ip netns delete.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 7, 4, 'Контейнер запущен с --pid=host. Что верно?', '["Он не видит процессов хоста", "Его сеть общая с сетью хоста", "Он видит процессы хоста, а остальные пространства остаются отдельными, пока их не изменили другими ключами", "Внутри него процессы нумеруются с единицы"]', 2, 'Ключ --pid=host оставляет контейнеру только PID-пространство хоста. Сеть, монтирование и остальное задают другие ключи, а нумерация с единицы бывает лишь в новом PID-пространстве.');
